const EDITORIAL_STANDARD_EFFECTIVE_DATE = "2026-08-29";
const MONTHS:Record<string,string>={ENE:"01",FEB:"02",MAR:"03",ABR:"04",MAY:"05",JUN:"06",JUL:"07",AGO:"08",SEP:"09",OCT:"10",NOV:"11",DIC:"12"};

// Mantiene la portada y los portales ordenados por fecha, aunque las notas nuevas
// se agreguen al final del archivo central de artículos.
articles.sort((a,b)=>String(b.dateIso||b.date).localeCompare(String(a.dateIso||a.date)));

 function articleDateKey(article:Article){
 const isoDate=article.dateIso?.slice(0,10);
 if(isoDate)return isoDate;
 const [day,month,year]=article.date.split(" ");
 return year&&MONTHS[month]&&day?`${year}-${MONTHS[month]}-${day.padStart(2,"0")}`:"";
}

function validateEditorialStandard(article:Article){
 if(articleDateKey(article)<EDITORIAL_STANDARD_EFFECTIVE_DATE)return;
 const features=article.features??[];
 const images=[article.image,...features.map(feature=>feature.image)];
 const uniqueImages=new Set(images);
 const missingAlt=!article.imageAlt?.trim()||features.some(feature=>!feature.alt.trim());

 if(!article.personalAngle||article.personalAngle.trim().length<80)throw new Error(`La nota ${article.slug} necesita una mirada personal de al menos 80 caracteres.`);
 if(!article.leadTitle?.trim()||article.leadTitle.trim().toLowerCase()==="lo que tenés que saber")throw new Error(`La nota ${article.slug} necesita un título de sección propio, no una fórmula genérica.`);
 if(features.length<2||uniqueImages.size<3)throw new Error(`La nota ${article.slug} necesita al menos tres imágenes diferentes: una principal y dos contextuales.`);
 if(missingAlt)throw new Error(`La nota ${article.slug} tiene imágenes sin texto alternativo.`);
 if(!article.sources?.length)throw new Error(`La nota ${article.slug} necesita al menos una fuente identificada.`);
 if(articleDateKey(article)>="2026-08-30"&&(article.sources.length<3||article.hideSources))throw new Error(`La nota ${article.slug} necesita al menos tres fuentes de imagen reconocidas y créditos visibles.`);
}

articles.forEach(validateEditorialStandard);

